444	// findSessionIndex returns the index of an existing session with the given ID,
445	// or the next available index if not found. This prevents duplicate session entries.
446	func (s *GitStore) findSessionIndex(ctx context.Context, basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
447		if existingSummary == nil {
448			return 0
449		}
450		for i := range len(existingSummary.Sessions) {
451			path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
452			if entry, exists := entries[path]; exists {
453				meta, err := s.readMetadataFromBlob(entry.Hash)
454				if err != nil {
455					logging.Warn(ctx, "failed to read session metadata during dedup check",
456						slog.Int("session_index", i),
457						slog.String("session_id", sessionID),
458						slog.String("error", err.Error()),
459					)
460					continue
461				}
462				if meta.SessionID == sessionID {
463					return i
464				}
465			}
466		}
467		return len(existingSummary.Sessions)
468	}
