11	// DiffTreeFiles returns the set of files changed between two commits using git diff-tree.
12	// For initial commits (commit1 is empty), use --root mode.
13	// repoDir is the path to the git repository working tree; the command runs in that directory.
14	// Returns a map of file paths for O(1) lookup.
15	func DiffTreeFiles(ctx context.Context, repoDir, commit1, commit2 string) (map[string]struct{}, error) {
16		files, err := diffTreeRaw(ctx, repoDir, commit1, commit2)
17		if err != nil {
18			return nil, err
19		}
20	
21		result := make(map[string]struct{}, len(files))
22		for _, f := range files {
23			result[f] = struct{}{}
24		}
25		return result, nil
26	}
