35	// diffTreeRaw runs git diff-tree in the given directory and returns the list of changed file paths.
36	func diffTreeRaw(ctx context.Context, dir, commit1, commit2 string) ([]string, error) {
37		var cmd *exec.Cmd
38		if commit1 == "" {
39			// Initial commit (no parent): list all files in the tree
40			cmd = exec.CommandContext(ctx, "git", "diff-tree", "--root", "--no-commit-id", "-r", "-z", commit2)
41		} else {
42			cmd = exec.CommandContext(ctx, "git", "diff-tree", "--no-commit-id", "-r", "-z", commit1, commit2)
43		}
44		cmd.Dir = dir
45	
46		var stdout, stderr bytes.Buffer
47		cmd.Stdout = &stdout
48		cmd.Stderr = &stderr
49	
50		if err := cmd.Run(); err != nil {
51			return nil, fmt.Errorf("git diff-tree failed: %w: %s", err, strings.TrimSpace(stderr.String()))
52		}
53	
54		return parseDiffTreeOutput(stdout.Bytes()), nil
55	}
56	
57	// parseDiffTreeOutput parses null-separated git diff-tree -r -z output.
58	// The format is: :<old-mode> <new-mode> <old-hash> <new-hash> <status>\0<path>\0
59	// For renames/copies: :<old-mode> <new-mode> <old-hash> <new-hash> <status>\0<old-path>\0<new-path>\0
60	func parseDiffTreeOutput(data []byte) []string {
61		if len(data) == 0 {
62			return nil
63		}
64	
65		// Split on null bytes
66		parts := bytes.Split(data, []byte{0})
67	
68		var files []string
69		i := 0
70		for i < len(parts) {
71			part := string(parts[i])
72	
73			switch {
74			case strings.HasPrefix(part, ":"):
75				// This is a status line like ":100644 100644 abc123 def456 M"
76				// The next part(s) are the path(s)
77				status := extractStatus(part)
78				i++
79				if i >= len(parts) {
80					break
81				}
82	
83				// First path
84				path := string(parts[i])
85				if path != "" {
86					files = append(files, path)
87				}
88				i++
89	
90				// Renames (R) and copies (C) have a second path
91				if (status == 'R' || status == 'C') && i < len(parts) {
92					path2 := string(parts[i])
93					if path2 != "" && !strings.HasPrefix(path2, ":") {
94						files = append(files, path2)
95						i++
96					}
97				}
98			default:
99				// Skip empty parts (trailing null byte) and unexpected content
100				i++
101			}
102		}
103	
104		return files
105	}
106	
107	// extractStatus extracts the single-char status from a diff-tree status line.
108	// Input format: ":100644 100644 abc123... def456... M" or similar
109	func extractStatus(statusLine string) byte {
110		// Status is the last non-space character in the metadata portion
111		// Format: :<old-mode> <new-mode> <old-hash> <new-hash> <status-letter>[score]
112		trimmed := strings.TrimSpace(statusLine)
113		if len(trimmed) == 0 {
114			return 0
115		}
116	
117		// Split by spaces and take the last field
118		fields := strings.Fields(trimmed)
119		if len(fields) < 5 {
120			return 0
121		}
122		statusField := fields[4]
123		if len(statusField) == 0 {
124			return 0
125		}
126		return statusField[0]
127	}
